1: // What: turns a measured light level into a preview boost and a plain-language note.
2: // Why: the preview must stay usable for framing in dim rooms, and a dark room must be named rather than hidden.
3: // Removed: a dark feed would look broken, and the player would never learn the measurement needs light.
4: import type { PreviewFrame } from './contracts.js';
5: 
6: export const DARK_LIGHT = 0.18;
7: export const DIM_LIGHT = 0.28;
8: const MAX_BOOST = 3.2;
9: 
10: /** Luma is 0–1. Below the dim threshold the preview is lifted, never the frames the SDK measures. */
11: export function previewBoost(light: number | null): number {
12:   if (light === null || !Number.isFinite(light)) return 1;
13:   if (light >= DIM_LIGHT) return 1;
14:   if (light <= 0) return MAX_BOOST;
15:   return Math.min(MAX_BOOST, DIM_LIGHT / light);
16: }
17: 
18: export function lightNote(light: number | null): string {
19:   if (light === null || !Number.isFinite(light)) return 'Camera preview. Nothing is recorded.';
20:   const pct = Math.round(Math.max(0, Math.min(1, light)) * 100);
21:   if (light < DARK_LIGHT) {
22:     return `Light ${pct}% — too dark. Add a lamp in front of you; the preview is brightened so you can frame.`;
23:   }
24:   if (light < DIM_LIGHT) {
25:     return `Light ${pct}% — dim. A lamp in front of you will help the measurement.`;
26:   }
27:   return `Light ${pct}%. Camera preview. Nothing is recorded.`;
28: }
29: 
30: const MIN_PREVIEW_WIDTH = 16;
31: const MAX_PREVIEW_WIDTH = 1920;
32: /** The preview schema caps height too; a portrait frame must not exceed it. */
33: const MAX_PREVIEW_HEIGHT = 1080;
34: 
35: /**
36:  * Shrinks a packed RGB frame to RGBA for a preview, and reports its brightness.
37:  * One sample per output pixel: the preview only has to show framing, not detail.
38:  */
39: export function downscaleRgbToRgba(
40:   source: Uint8Array,
41:   sourceWidth: number,
42:   sourceHeight: number,
43:   strideBytes: number,
44:   outWidth: number,
45: ): PreviewFrame {
46:   if (
47:     !Number.isInteger(sourceWidth) ||
48:     !Number.isInteger(sourceHeight) ||
49:     sourceWidth < 2 ||
50:     sourceHeight < 2
51:   ) {
52:     throw new Error('The camera frame had no size.');
53:   }
54:   if (!Number.isInteger(strideBytes) || strideBytes < sourceWidth * 3) {
55:     throw new Error('The camera frame stride is too small for its width.');
56:   }
57:   if (source.byteLength < strideBytes * sourceHeight) {
58:     throw new Error('The camera frame is shorter than its size says.');
59:   }
60:   // One scale, constrained by both caps, so the aspect ratio holds and the schema never rejects it.
61:   const requested = Math.max(MIN_PREVIEW_WIDTH, Math.min(MAX_PREVIEW_WIDTH, Math.round(outWidth)));
62:   const scale = Math.min(requested / sourceWidth, MAX_PREVIEW_HEIGHT / sourceHeight);
63:   const width = Math.max(MIN_PREVIEW_WIDTH, Math.round(sourceWidth * scale));
64:   const height = Math.max(2, Math.round(sourceHeight * scale));
65:   const rgba = new Uint8Array(width * height * 4);
66:   const xs = new Int32Array(width);
67:   for (let x = 0; x < width; x += 1) {
68:     xs[x] = Math.min(sourceWidth - 1, Math.floor(((x + 0.5) * sourceWidth) / width));
69:   }
70:   let lumaSum = 0;
71:   let out = 0;
72:   for (let y = 0; y < height; y += 1) {
73:     const sourceRow = Math.min(sourceHeight - 1, Math.floor(((y + 0.5) * sourceHeight) / height)) * strideBytes;
74:     for (let x = 0; x < width; x += 1) {
75:       const at = sourceRow + xs[x] * 3;
76:       const red = source[at];
77:       const green = source[at + 1];
78:       const blue = source[at + 2];
79:       rgba[out] = red;
80:       rgba[out + 1] = green;
81:       rgba[out + 2] = blue;
82:       rgba[out + 3] = 255;
83:       lumaSum += (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 255;
84:       out += 4;
85:     }
86:   }
87:   return { width, height, rgba, light: lumaSum / (width * height) };
88: }

