13: }
14: 
15: export interface DoctorCheckLike {
16:   id: string;
17:   status: string;
18:   detail: string;
19: }
20: 
21: const DEFAULT_MISSING_KEY =
22:   'The SmartSpectra key is missing. Add SMARTSPECTRA_API_KEY to .env, then restart.';
23: 
24: export function keyStatusFromChecks(checks: readonly DoctorCheckLike[]): SetupKeyResult {
25:   const check = checks.find((candidate) => candidate.id === 'sensing-key');
26:   if (!check) {
27:     return { status: 'error', detail: 'The key check did not report a result.' };
28:   }
29:   return check.status === 'pass'
