57:     return { canStart: false, reasons: ['Checking the SmartSpectra key…'] };
58:   }
59:   if (input.keyStatus === 'missing') {
60:     return { canStart: false, reasons: [input.keyDetail || DEFAULT_MISSING_KEY] };
61:   }
62:   if (input.keyStatus === 'error') {
63:     return {
64:       canStart: false,
65:       reasons: ['The key check could not run. Open Help and copy diagnostics.'],
66:     };
67:   }
