1: // What: the three framing checks Setup shows, derived from the SDK's one active validation code.
2: // Why: Setup must name what to fix before a session, using the same hints the sensing screen gets.
3: // Removed: framing advice would exist only in the README, and Start could open a session that measures nothing.
4: 
5: /** The SDK's integer validation codes. Values are stable across SDK versions. */
6: export const VALIDATION = {
7:   ok: 0,
8:   noFaceFound: 1,
9:   multipleFacesFound: 2,
10:   faceNotCentered: 3,
11:   faceSizeOutOfRange: 4,
12:   tooDark: 5,
13:   tooBright: 6,
14:   chestNotVisible: 7,
15:   cameraTuning: 10,
16:   frameRateTooLow: 11,
17:   excessiveMotion: 12,
18:   faceTooClose: 13,
19:   faceTooFar: 14,
20:   faceTooHigh: 15,
21:   faceTooLow: 16,
22:   faceNotForward: 17,
23: } as const;
24: 
25: export type FramingState = 'unknown' | 'pass' | 'fail';
26: 
27: export interface FramingChecks {
28:   face: FramingState;
29:   chest: FramingState;
30:   light: FramingState;
31: }
32: 
33: export const UNKNOWN_FRAMING: FramingChecks = {
34:   face: 'unknown',
35:   chest: 'unknown',
36:   light: 'unknown',
37: };
38: 
39: const FACE_CODES = new Set<number>([
40:   VALIDATION.noFaceFound,
41:   VALIDATION.multipleFacesFound,
42:   VALIDATION.faceNotCentered,
43:   VALIDATION.faceSizeOutOfRange,
44:   VALIDATION.faceTooClose,
45:   VALIDATION.faceTooFar,
46:   VALIDATION.faceTooHigh,
47:   VALIDATION.faceTooLow,
48:   VALIDATION.faceNotForward,
49: ]);
50: 
51: const LIGHT_CODES = new Set<number>([VALIDATION.tooDark, VALIDATION.tooBright]);
52: 
53: /**
54:  * The SDK reports one current code, not three independent booleans. A code that fixes one check
55:  * leaves the others unknown rather than borrowing an old pass from a different frame.
56:  */
57: export function framingFromValidation(code: number): FramingChecks {
58:   if (code === VALIDATION.ok) {
59:     return { face: 'pass', chest: 'pass', light: 'pass' };
60:   }
61:   if (code === VALIDATION.chestNotVisible) {
62:     return { face: 'pass', chest: 'fail', light: 'unknown' };
63:   }
64:   if (FACE_CODES.has(code)) {
65:     return { face: 'fail', chest: 'unknown', light: 'unknown' };
66:   }
67:   if (LIGHT_CODES.has(code)) {
68:     return { face: 'unknown', chest: 'unknown', light: 'fail' };
69:   }
70:   return UNKNOWN_FRAMING;
71: }
72: 
73: export function framingReady(checks: FramingChecks): boolean {
74:   return checks.face === 'pass' && checks.chest === 'pass' && checks.light === 'pass';
75: }
76: 
77: /** A text status per check, so the result never depends on colour alone. */
78: export function framingStatusText(state: FramingState): string {
79:   if (state === 'pass') return 'OK';
80:   if (state === 'fail') return 'Fix';
81:   return 'Waiting';
82: }

