379:     let stopFailed = false;
380:     if (flow.screen === 'sensing' || (revoking && startPending.current)) {
381:       try {
382:         const meta = await bridge.stopSession();
383:         settleSession(meta.id, stoppedNote(meta));
384:         dispatch({ type: 'clearError' });
385:       } catch {
386:         stopFailed = true;
387:         dispatch({ type: 'error', message: 'The session could not be stopped.' });
388:       }
389:     }
390:     try {
391:       const next = await bridge.setConsent(!grantedNow.current);
392:       if (!stopFailed) dispatch({ type: 'clearError' });
393:       grantedNow.current = next.granted;
394:       dispatch({ type: 'consentChanged', granted: next.granted });
395:     } catch {
