403:   async function onStart(): Promise<void> {
404:     if (!bridge || flow.screen !== 'setup' || !gate.canStart || startPending.current) return;
405:     revokedDuringStart.current = false;
406:     startPending.current = true;
407:     setStarting(true);
408:     try {
409:       const started = await bridge.startSession(timeControl);
410:       adoptSession(started.sessionId, started.startedAtEpochMs);
411:       // A terminal event may have arrived before the start response completed.
412:       if (terminalSessionRef.current === started.sessionId) return;
413:       if (revokedDuringStart.current || !grantedNow.current) {
414:         try {
415:           const meta = await bridge.stopSession();
416:           settleSession(meta.id, stoppedNote(meta));
417:         } catch {
418:           // Consent revocation has normally finalized the session already, so stopSession
419:           // rejects. The screen must not keep claiming it is sensing a session that is gone.
420:           settleSession(started.sessionId, 'The session stopped after consent was withdrawn.');
421:         }
422:         return;
423:       }
424:     } catch (caught: unknown) {
425:       if (!revokedDuringStart.current && grantedNow.current) {
426:         dispatch({ type: 'error', message: readIpcError(caught, 'session_failed') });
427:         // Main released the preview before the failed start. Rebuild it so Setup is usable again.
428:         setPreview('idle');
429:         setPreviewAttempt((attempt) => attempt + 1);
430:       }
431:     } finally {
432:       startPending.current = false;
433:       setStarting(false);
434:     }
435:   }
