374: function median(values: readonly number[]): number {
375:   const sorted = [...values].sort((a, b) => a - b);
376:   const mid = Math.floor(sorted.length / 2);
377:   if (sorted.length % 2 === 1) return sorted[mid];
378:   return (sorted[mid - 1] + sorted[mid]) / 2;
379: }

