361: /**
362:  * One status region. An operation error outranks a sensing error, which outranks a live hint; the
363:  * session note is last. Nothing here is written by a screen that happens to render later.
364:  */
365: export function statusFor(input: StatusInput): StatusLine {
366:   if (input.error) return { text: input.error, tone: 'error', urgent: true };
367:   if (input.sdkError) return { text: input.sdkError, tone: 'error', urgent: true };
368:   if (input.screen === 'sensing' && input.hint) {
369:     return { text: input.hint, tone: 'note', urgent: false };
370:   }
371:   return { text: input.notice, tone: 'default', urgent: false };
372: }
