374: /** The live sensing sentence. It always says something while the camera is measuring. */
375: export function sensingHint(
376:   samples: readonly PulseSample[],
377:   validation: ValidationMessage | null,
378: ): string | null {
379:   if (validation && validation.code !== 0) return validation.hint;
380:   if (samples.length === 0) return 'Waiting for a face.';
381:   const latest = samples[samples.length - 1];
382:   if (!latest.stable || latest.confidence < CONFIDENCE_FLOOR) {
383:     return samples.some((sample) => sample.stable && sample.confidence >= CONFIDENCE_FLOOR)
384:       ? 'Low confidence.'
385:       : 'Validating.';
386:   }
387:   return 'Sensing.';
388: }

