210:       return { ...state, screen: helpReturnScreen(state), helpReturn: null };
211: 
212:     case 'openStopped':
213:       if (!state.stoppedSessionId) return state;
214:       return { ...state, screen: 'stopped' };
215: 
216:     case 'openGames':
217:       if (state.screen !== 'stopped' && state.screen !== 'review') return state;
218:       if (!currentSessionId(state)) return state;
219:       return { ...state, screen: 'games' };
