347: export interface StatusInput {
348:   error: string | null;
349:   sdkError: string | null;
350:   screen: Screen;
351:   hint: string | null;
352:   notice: string;
353: }
354: 
355: export interface StatusLine {
356:   text: string;
357:   tone: FlowTone;
358:   urgent: boolean;
359: }
360: 
361: /**
362:  * One status region. An operation error outranks a sensing error, which outranks a live hint; the
363:  * session note is last. Nothing here is written by a screen that happens to render later.
364:  */
365: export function statusFor(input: StatusInput): StatusLine {
366:   if (input.error) return { text: input.error, tone: 'error', urgent: true };
367:   if (input.sdkError) return { text: input.sdkError, tone: 'error', urgent: true };
368:   if (input.screen === 'sensing' && input.hint) {
369:     return { text: input.hint, tone: 'note', urgent: false };
370:   }
371:   return { text: input.notice, tone: 'default', urgent: false };
372: }
373: 
374: /** The live sensing sentence. It always says something while the camera is measuring. */
375: export function sensingHint(
376:   samples: readonly PulseSample[],
377:   validation: ValidationMessage | null,
378: ): string | null {
379:   if (validation && validation.code !== 0) return validation.hint;
380:   if (samples.length === 0) return 'Waiting for a face.';
381:   const latest = samples[samples.length - 1];
382:   if (!latest.stable || latest.confidence < CONFIDENCE_FLOOR) {
383:     return samples.some((sample) => sample.stable && sample.confidence >= CONFIDENCE_FLOOR)
384:       ? 'Low confidence.'
385:       : 'Validating.';
386:   }
387:   return 'Sensing.';
388: }

